      "rank": 1,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks opened a new regime of precision measurement, with fundamental consequences for timekeeping, tests of physical laws, and probing quantum systems.",
        "attribution": "Katori and Ye developed complementary approaches that established the field; credit to both is well supported.",
        "maturity": "The techniques have been independently realized and refined for years, with a sustained record of improved performance and new applications.",
        "uncertainties": [
          "The relative emphasis between clock invention and the broader precision-measurement impact would need careful framing."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B030",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped-ion quantum computing joined a clear theoretical architecture to controlled experimental demonstrations, making it a foundational advance in quantum information physics.",
        "attribution": "Cirac and Zoller supplied central theoretical proposals, while Blatt's experiments helped establish and develop the approach.",
        "maturity": "The platform has been reproduced and extended across laboratories, though scalable fault-tolerant computing remains an active challenge.",
        "uncertainties": [
          "The proposed contribution is broad and would need a precise boundary between foundational trapped-ion demonstrations and later platform development."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B026",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Jean Dalibard",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices made controlled quantum many-body systems experimentally accessible and enabled tests of fundamental models of matter.",
        "attribution": "Zoller's theoretical work and the experimental programs associated with Bloch and Dalibard are central; the five-name credit set reflects a broader collaborative history.",
        "maturity": "The methods and physical results have been extensively reproduced and expanded, although the most ambitious simulation goals continue to develop.",
        "uncertainties": [
          "The discovery is a broad program with contributions from several groups, so selecting a compact laureate set is difficult."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B037",
      "proposed_laureates": [
        "Christian J. Bordé",
        "David E. Pritchard",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry brought matter-wave interference to precision measurement and created a versatile way to study gravity, inertial forces, and quantum coherence.",
        "attribution": "These researchers made influential, complementary contributions to the development and experimental realization of atom interferometers.",
        "maturity": "The technique has been demonstrated in many settings and has supported decades of precision experiments.",
        "uncertainties": [
          "The field grew through multiple parallel efforts, making the boundary of the central invention difficult to define."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B047",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how quantum information can be protected despite noise and established the conceptual route to fault-tolerant quantum computation.",
        "attribution": "Shor and Steane introduced landmark codes, and Kitaev developed influential fault-tolerant and topological approaches; the contributions are distinct but connected.",
        "maturity": "The principles have been experimentally tested and are central to current quantum computing efforts, while large-scale fault tolerance is not yet achieved.",
        "uncertainties": [
          "The award case rests on foundational theory whose full practical realization remains in progress."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Allan H. MacDonald",
        "Pablo Jarillo-Herrero",
        "Rafi Bistritzer"
      ],
      "assessment": {
        "nobel_worthiness": "Twisted bilayer graphene revealed that tuning geometry can produce strongly correlated electronic phases, opening a new and productive direction in quantum materials.",
        "attribution": "Bistritzer and MacDonald predicted the flat-band mechanism, and Jarillo-Herrero's experiments established the striking correlated states.",
        "maturity": "The phenomenon has been reproduced and extended to other moiré systems, but its microscopic interpretation and the status of superconductivity remain active topics.",
        "uncertainties": [
          "The underlying mechanisms of superconductivity and some correlated phases are not settled."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Peter F. Moulton",
        "Ursula Keller",
        "Wilson Sibbett"
      ],
      "assessment": {
        "nobel_worthiness": "Titanium-sapphire lasers and passive mode-locking made reliable, tunable femtosecond pulses broadly available and enabled major advances in ultrafast science.",
        "attribution": "Moulton's laser medium and the complementary mode-locking work of Keller and Sibbett provide a plausible, distinct attribution.",
        "maturity": "The technology has been adopted widely and supported decades of reproducible experiments, including foundational work in ultrafast and attosecond physics.",
        "uncertainties": [
          "The contribution is an enabling technology, and the division of credit among invention, refinement, and practical adoption needs care."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page Jr."
      ],
      "assessment": {
        "nobel_worthiness": "WMAP's precision mapping of the cosmic microwave background transformed cosmology into a quantitatively constrained field and tested models of the early universe.",
        "attribution": "Bennett and Page led central experimental and instrumental work, while Spergel's analysis helped establish the cosmological interpretation.",
        "maturity": "The measurements have been checked against later observations and remain a landmark dataset for precision cosmology.",
        "uncertainties": [
          "The credit set must distinguish WMAP's specific contribution from prior CMB discoveries and later precision surveys."
        ]
      }
    }
  ]
}
